contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint balAfter = address(c).balance;

        // If go() does not revert, the entire msg.value was just transferred into c
        // and then the whole balance was sent to owner, leaving c with exactly msg.value
        // only in the case where the external call to the hard-coded target failed.
        // When the call succeeds, c's balance is zero. In both cases it is at most amount.
        assert(reverted || balAfter <= amount);
    }
}

